    {
      "source_concept": "prediction errors",
      "target_concept": "gradients",
      "intended_fact": "Prediction errors are used by backpropagation to calculate gradients.",
      "confidence": 0.98,
      "reason": "Backpropagation computes the partial derivatives (gradients) of a loss function with respect to weights; these gradients are functions of the prediction errors.",
      "gap_ids": [
        "question_0002"
      ],
      "added_knowledge": "Clarifies that errors are inputs to the gradient computation, not the output."
    },
